-- SLA attribution join snippet
SELECT r.route_id, r.sla_target, f.avg_latency_1h, CASE WHEN f.avg_latency_1h > r.sla_target THEN 1 ELSE 0 END as breach_flag
FROM analytics.routes_dim r JOIN analytics.nearline_features_v1 f ON r.route_id = f.route_id WHERE f.feature_ts >= dateadd(hour, -1, current_timestamp());
